"use client";

import React from 'react';

export default function ProductCard({ product, onViewDetails }) {
  const imgSrc = product.image_url || '/flowers/bouquetwithglitter.jfif';

  let startingPrice = null;
  if (product.pricing && Array.isArray(product.pricing) && product.pricing.length && product.pricing[0].price) {
    startingPrice = product.pricing[0].price;
  }

  return (
    <div
      onClick={() => onViewDetails && onViewDetails(product)}
      class="product-card h-full cursor-pointer group"
    >
      <div class="relative overflow-hidden h-52 sm:h-60 bg-slate-100">
        <img
          src={imgSrc}
          alt={product.name}
          class="card-img-top w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
          loading="lazy"
        />
      </div>
      <div class="p-4 sm:p-5 text-center flex flex-col flex-grow bg-white">
        <h5 class="font-bold text-slate-900 text-base sm:text-lg mb-1 line-clamp-1">
          {product.name}
        </h5>
        {startingPrice && (
          <div class="text-xs text-slate-500 mb-3 font-medium">
            Starting at <span class="font-bold text-rose-600 text-sm">₱{startingPrice}</span>
          </div>
        )}
        <div class="mt-auto pt-2">
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              if (onViewDetails) onViewDetails(product);
            }}
            class="btn-shadcn-primary w-full py-2.5 px-4 font-semibold text-xs sm:text-sm flex items-center justify-center gap-2 group/btn shadow-md hover:shadow-lg hover:shadow-rose-500/25 active:scale-[0.98] transition-all view-price-btn"
          >
            <i class="fa-solid fa-eye text-xs group-hover/btn:scale-110 transition-transform"></i>
            <span>View</span>
          </button>
        </div>
      </div>
    </div>
  );
}
